async function action(a,b){try{if(await runExtraAction(a,b))return;if(a==='edit-benchmark'){editBenchmark(b);return}if(a==='run-rules'){await runRules(b.dataset.contentId);return}if(a==='retry'){await render();return}if(a==='open-add'){openRecordForm();return}if(a==='open-performance'){openPerformanceForm();return}if(a==='edit-record'){const x=state.records.find(c=>c.id===b.dataset.id);openRecordForm(x);return}if(a==='delete-record'){if(confirm('确定删除这条内容记录？')){await api(`/api/contents/${b.dataset.id}`,{method:'DELETE'});state.selectedRecords=state.selectedRecords.filter(id=>id!==b.dataset.id);await render();toast('记录已删除')}return}if(a==='export-content-csv'){downloadApi('/api/export/contents');return}if(a==='export-report'){downloadApi('/api/report/export');return}if(a==='export-anonymized'){downloadApi('/api/export/anonymized');return}if(a==='handover'){downloadApi('/api/handover/export?format=markdown');return}if(a==='audit'){const rows=await api('/api/audit');showInfo('最近操作记录',rows.slice(0,20).map(x=>`${escapeHtml(x.created_at.slice(0,16))} · ${escapeHtml(x.actor)} · ${escapeHtml(x.action)} · ${escapeHtml(x.detail)}`).join('<br>')||'暂无操作记录');return}if(a==='test-ai'){toast('正在通过后端测试模型连通性…');const r=await api('/api/ai/test',{method:'POST'});toast(`${r.message} · ${r.elapsed_ms}ms`);return}if(a==='save-model-profile'){const data=formAIData();if(!data)return;const saved=await api('/api/ai/configs',{method:'POST',body:JSON.stringify(data)});await api(`/api/ai/configs/${saved.id}/activate`,{method:'POST'});await render();toast('新模型配置已保存并启用');return}if(a==='activate-model'){await api(`/api/ai/configs/${b.dataset.id}/activate`,{method:'POST'});await render();toast('已切换当前模型');return}if(a==='generate'||a==='generate-rules'){const box=qs('#recommendationBox');if(box)box.innerHTML='<div class="chart-empty loading-state">正在生成排期建议…</div>';if(b)b.disabled=true;toast(a==='generate'?'正在请求 AI 分析，最长等待 60 秒…':'正在使用本地规则引擎…');state.recommendation=await api(`/api/ai/recommend${a==='generate-rules'?'?force_rule=true':''}`,{method:'POST'});if(box)box.innerHTML=recommendationView(state.recommendation);bindRecommendation();if(b)b.disabled=false;toast(state.recommendation.source_label);return}if(a==='edit-suggestion'){toast('修改日期、时间或标题后即可采纳');return}if(a==='cancel-suggestion'){const index=Number(b.dataset.index),items=currentEditedRecommendations(),previous=state.recommendation;items.splice(index,1);const saved=await api(`/api/recommendations/${previous.id}`,{method:'PATCH',body:JSON.stringify({recommendations:items})});state.recommendation={...previous,recommendations:saved.recommendations};qs('#recommendationBox').innerHTML=recommendationView(state.recommendation);bindRecommendation();return}if(a==='adopt'){const items=currentEditedRecommendations(),overlaps=items.map(item=>({item,schedule:state.calendar.find(row=>row.content_id===item.target_content_id&&row.status==='待发布')})).filter(row=>row.schedule);let adjusted=0;if(overlaps.length){if(!confirm(`其中 ${overlaps.length} 条内容已有排期。确认用当前建议调整已有排期？`))return;for(const {item,schedule} of overlaps){await api(`/api/schedule/${schedule.id}`,{method:'PATCH',body:JSON.stringify({planned_date:item.planned_date,planned_time:item.time_slot,title:item.title,category:item.content_type,platform:item.platform,owner:item.owner||schedule.owner})});adjusted++}}const existingIds=new Set(overlaps.map(x=>x.item.target_content_id));const remaining=items.filter(item=>!existingIds.has(item.target_content_id));let created=0;if(remaining.length){const res=await api('/api/schedule/adopt',{method:'POST',body:JSON.stringify({recommendation_id:b.dataset.id,items:remaining})});created=res.created}await go('calendar');toast(`已写入 ${created} 条新排期，调整 ${adjusted} 条已有排期`);return}if(a==='week-prev'){state.monthOffset--;await render();return}if(a==='week-next'){state.monthOffset++;await render();return}if(a==='week-today'){state.monthOffset=0;await render();return}if(a==='records-prev'){state.recordsPage=Math.max(1,state.recordsPage-1);await renderRecordsOnly();return}if(a==='records-next'){state.recordsPage++;await renderRecordsOnly();return}if(a==='bulk-publish'||a==='bulk-unpublish'){await bulkRecords('set_status',a==='bulk-publish'?WORKFLOW.published:WORKFLOW.unpublished);return}if(a==='bulk-delete'){if(confirm(`确定删除已选择的 ${state.selectedRecords.length} 条记录？`))await bulkRecords('delete');return}if(a==='export-calendar'){downloadApi('/api/schedule/export');return}if(a==='edit-schedule'){editSchedule(b.dataset.id);return}if(a==='publish'){publishSchedule(b.dataset.id);return}}catch(e){if(['generate','generate-rules'].includes(a)){const box=qs('#recommendationBox');if(box)box.innerHTML=`<div class="chart-empty error-text">排期建议生成失败：${escapeHtml(e.message)}。请检查规则集、未发布内容和当前账号权限后重试。</div>`;if(b)b.disabled=false}toast(e.message)}}
function currentEditedRecommendations(){const r=state.recommendation;if(!r)return[];return r.recommendations.map((x,i)=>({...x,title:qs(`[data-rec-title="${i}"]`)?.textContent.trim()||x.title,planned_date:qs(`[data-rec-date="${i}"]`)?.value||x.planned_date,time_slot:qs(`[data-rec-time="${i}"]`)?.value||x.time_slot}))}
function bindRecommendation(){qsa('#recommendationBox [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b))}
function openManualSchedule(content){
 const existing=(state.calendar||[]).find(x=>x.content_id===content.id&&x.status==='待发布');
 const initialDate=existing?.planned_date||content.published_at.slice(0,10);
 const initialTime=existing?.planned_time||'19:30';
 showModal(`<div class="modal-head"><div><h2>${existing?'调整手动排期':'手动排期'}</h2><p>${escapeHtml(content.title)} · 排期由当前登录用户负责记录</p></div><button class="modal-close" data-action="close">×</button></div><form id="manualScheduleForm" class="modal-form"><div class="form-grid"><div class="form-field"><label>发布时间</label><input name="planned_date" type="date" required value="${escapeHtml(initialDate)}"/></div><div class="form-field"><label>时间段</label><select name="planned_time">${policy.time_windows.map(t=>`<option ${t===initialTime?'selected':''}>${t}</option>`).join('')}</select></div></div><p class="form-help">手动排期会按项目规则校验日期和时间；已有排期将更新原记录并保留人工来源。</p><div class="form-actions"><button type="button" class="btn-secondary" data-action="close">取消</button><button class="btn-primary">保存排期</button></div></form>`);
 qs('#manualScheduleForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{if(existing){await api(`/api/schedule/${existing.id}`,{method:'PATCH',body:JSON.stringify(data)})}else{await api('/api/schedule/manual',{method:'POST',body:JSON.stringify({content_id:content.id,planned_date:data.planned_date+'T00:00:00',planned_time:data.planned_time})})}closeModal();await render();toast(existing?'排期已更新':'手动排期已保存')}catch(err){toast(err.message)}}
}
